+    let temp = tempfile::tempdir().unwrap();
+    let from = temp.path().join("stage");
+    let to = temp.path().join("destination");
+    std::fs::create_dir(&from).unwrap();
+    std::fs::create_dir(&to).unwrap();
+    assert!(rename_new(&from, &to).is_err());
+    assert!(from.is_dir());
+    assert!(to.is_dir());
